//! Kotlin: the JNA bindings in `package com.azul` (`target/codegen/kotlin/Azul.kt`,
//! generated by `doc/src/codegen/v2/lang_kotlin`).
//!
//! Spellings: the raw C functions are `@JvmStatic external fun`s on one
//! `object AzulNative<Module>` per api module (`AzulNativeCss.AzPixelValue_px(..)`),
//! C-like enums are `enum class`es with a `value: Int` (`LayoutDisplay.Flex.value`),
//! structs and unions are JNA classes with `@JvmField var`s, built as
//! expressions with `apply` (`AzColorU.ByValue().apply { r = 255.toByte(); .. }`;
//! a union also calls `setType("Variant")`). A Vec goes through the
//! generated `azVec(AzulNativeVec::AzXxxVec_copyFromPtr, ..)` helper.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, java::native_class, unicode_u4,
        variant_ctor_method, ExprSyntax,
    },
    lower_types::is_c_like_enum,
    CodegenBackend, GeneratedFile,
};

/// The Kotlin printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Kotlin;

const KEYWORDS: &[&str] = &[
    "as", "break", "class", "continue", "do", "else", "false", "for", "fun", "if", "in",
    "interface", "is", "null", "object", "package", "return", "super", "this", "throw", "true",
    "try", "typealias", "typeof", "val", "var", "when", "while",
];

fn field(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("`{name}`")
    } else {
        name.to_string()
    }
}

/// `AzX.ByValue().apply { a = ..; b = .. }`
fn apply_block(ty: &str, statements: Vec<Doc>, broken: bool) -> Doc {
    Doc::cat(vec![
        Doc::text(format!("Az{ty}.ByValue().apply ")),
        Doc::list("{", statements, "; ", "}", true, broken, false),
    ])
}

impl ExprSyntax for Kotlin {
    fn int(&self, value: i128, ty: Prim) -> String {
        match ty {
            Prim::U8 | Prim::I8 | Prim::Bool => format!("{value}.toByte()"),
            Prim::U16 | Prim::I16 => format!("{value}.toShort()"),
            Prim::U64 | Prim::I64 | Prim::Usize | Prim::Isize => format!("{value}L"),
            _ => value.to_string(),
        }
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let (t, suffix) = if ty == Prim::F64 { ("Double", "") } else { ("Float", "f") };
        match text {
            "nan" => format!("{t}.NaN"),
            "inf" => format!("{t}.POSITIVE_INFINITY"),
            "-inf" => format!("{t}.NEGATIVE_INFINITY"),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        // JNA maps the C `bool` fields to `Byte`
        format!("{}.toByte()", u8::from(b))
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("azStr(\"{}\")", escape_quoted(s, &['$'], &unicode_u4)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(
            format!("{}.Az{class}_{}", native_class(class), snake_to_lower_camel(method)),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("{ty}.{variant}.value")),
            EnumShape::Tagged => Doc::call(
                format!("{}.Az{ty}_{}", native_class(ty), variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let mut st = vec![Doc::text(format!(
                    "{variant}.tag = Az{ty}_Tag.{variant}.value.toByte()"
                ))];
                if let Some(payload) = args.into_iter().next() {
                    st.push(Doc::cat(vec![Doc::text(format!("{variant}.payload = ")), payload]));
                }
                st.push(Doc::text(format!("setType(\"{variant}\")")));
                apply_block(ty, st, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let st = fields
            .into_iter()
            .map(|(k, d)| Doc::cat(vec![Doc::text(format!("{} = ", field(&k))), d]))
            .collect();
        apply_block(ty, st, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("AzulNativeVec.Az{ty}_create()"));
        }
        let helper = if is_c_like_enum(elem) { "azVecInts" } else { "azVec" };
        let mut args = vec![Doc::text(format!("AzulNativeVec::Az{ty}_copyFromPtr"))];
        args.extend(items);
        Doc::call(helper, args, broken)
    }

    fn unsupported(&self, _what: &str) -> Doc {
        Doc::text("TODO(\"not expressible with the Kotlin bindings\")")
    }
}

const HELPERS: &str = r"// Copies the items into native memory; AzXxxVec_copyFromPtr clones them.
internal fun <V> azVec(copy: (Pointer?, Long) -> V, vararg items: Structure): V {
    val size = items[0].size()
    val mem = Memory(size.toLong() * items.size)
    items.forEachIndexed { i, item ->
        item.write()
        mem.write(i.toLong() * size, item.pointer.getByteArray(0, size), 0, size)
    }
    return copy(mem, items.size.toLong())
}

// The same for a Vec of C-like enum values.
internal fun <V> azVecInts(copy: (Pointer?, Long) -> V, vararg items: Int): V {
    val mem = Memory(4L * items.size)
    items.forEachIndexed { i, item -> mem.setInt(4L * i, item) }
    return copy(mem, items.size.toLong())
}

internal fun azStr(s: String): AzString.ByValue {
    val bytes = s.toByteArray(Charsets.UTF_8)
    val mem = Memory(maxOf(1, bytes.size).toLong())
    mem.write(0, bytes, 0, bytes.size)
    return AzulNativeStr.AzString_fromUtf8(mem, bytes.size.toLong())
}
";

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Kotlin, item) {
        out.push_str(&format!("// {line}\n"));
    }
    let name = item.name.lower_camel();
    let ty = if is_c_like_enum(&item.ty) {
        "Int".to_string()
    } else {
        format!("Az{}.ByValue", item.ty)
    };
    match item_doc(&Kotlin, item) {
        Ok(doc) => out.push_str(&format!(
            "fun {name}(): {ty} {{\n    return {}\n}}\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "// not expressible with the Kotlin bindings: {reason}\nfun {name}(): {ty}? = null\n"
        )),
    }
    out
}

impl CodegenBackend for Kotlin {
    fn lang(&self) -> &'static str {
        "kotlin"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["kt"]
    }

    fn display_name(&self) -> &'static str {
        "Kotlin"
    }

    fn extension(&self) -> &'static str {
        "kt"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "// Generated by azul-css codegen (Kotlin). Do not edit by hand.\npackage \
             com.azul\n\nimport com.sun.jna.Memory\nimport com.sun.jna.Pointer\nimport \
             com.sun.jna.Structure\n",
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out.push('\n');
        out.push_str(HELPERS);
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from("package com.azul\n\nfun main() {\n");
        for item in &m.items {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "    val {name}Value = {name}()\n    println(\"{name}: ${{{name}Value.len}} properties\")\n"
            ));
        }
        main.push_str("}\n");
        vec![
            GeneratedFile {
                path: "build.gradle.kts".to_string(),
                contents: GRADLE.to_string(),
            },
            GeneratedFile {
                path: "settings.gradle.kts".to_string(),
                contents: "rootProject.name = \"azul-styles\"\n".to_string(),
            },
            GeneratedFile {
                path: "src/main/kotlin/Styles.kt".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "src/main/kotlin/Main.kt".to_string(),
                contents: main,
            },
        ]
    }
}

const GRADLE: &str = r#"// Copy target/codegen/kotlin/Azul.kt into src/main/kotlin/, then
//   gradle build && java -Djna.library.path=<dir of libazul> -jar build/libs/azul-styles.jar
plugins {
    kotlin("jvm") version "2.3.21"
    application
}

repositories {
    mavenCentral()
}

dependencies {
    implementation("net.java.dev.jna:jna:5.14.0")
}

application {
    mainClass.set("com.azul.MainKt")
}
"#;
